<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Content;use Acorn\SafetyHealthcheck\Database\Schema;use RuntimeException;final class ContentPublisher{public function createDraftFromPublished(int$user):int{global$wpdb;$live=(new ContentVersionRepository)->getPublished();$parts=explode('.',$live['version_key']);$key=$parts[0].'.'.((int)($parts[1]??0)+1);$wpdb->insert(Schema::table('content_versions'),['version_key'=>$key,'status'=>'draft','created_by'=>$user,'created_at'=>current_time('mysql'),'notes'=>'Draft cloned from '.$live['version_key']]);$id=(int)$wpdb->insert_id;foreach((new QuestionRepository)->forVersion((int)$live['id'])as$q){unset($q['id']);$q['content_version_id']=$id;$wpdb->insert(Schema::table('questions'),$q);}return$id;}public function publish(int$id,int$user):int{global$wpdb;$missing=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Schema::table('questions').' q WHERE q.content_version_id=%d AND q.is_active=1 AND (q.reviewed_by="" OR q.source_json="")',$id));if($missing)throw new RuntimeException('Review metadata is incomplete.');$wpdb->update(Schema::table('content_versions'),['status'=>'retired'],['status'=>'published']);$wpdb->update(Schema::table('content_versions'),['status'=>'published','published_at'=>current_time('mysql')],['id'=>$id]);return$id;}}
